1	/**
2	 * @cipherbox/sdk - Durable rotation high-water state machine
3	 *
4	 * Hoists the durable anti-rollback CORE LOGIC (ROT-07) into the SDK so it is
5	 * unit-tested with Vitest -- apps/web supplies only a thin, untested
6	 * IndexedDB-backed HighWaterStore adapter (68-06) and calls enforceResolved
7	 * from resolveIpnsRecord.
8	 *
9	 * Maintains two independent monotonic-max floors per nodeId:
10	 *   - generation: the M1 cross-generation rollback defense (design §4.3)
11	 *   - seq: the within-generation sequence rollback defense (design §6.5)
12	 *
13	 * Both floors -- plus the optional SC#3 ECIES wrapped-key checkpoint -- are
14	 * read through a SINGLE injected `HighWaterStore` seam on every access --
15	 * there is NO in-instance cache -- so a fresh state machine constructed over
16	 * the SAME backing store observes previously-written floors (the
17	 * restart/persistence semantics proven at the logic tier).
18	 *
19	 * enforceResolved is a pure pass/throw pre-unseal gate -- it never returns
20	 * or computes any AAD/unseal parameter. The AAD generation is sourced from
21	 * the parent mirror in the unrelated unseal path.
22	 *
23	 * TS/Rust behavioral-equivalence contract (SC#5, T-70-03/T-70-04): this
24	 * orchestration layer's field-bump helper is a non-atomic read-then-put,
25	 * exactly like the Rust twin's `bump_floor` (`crates/sdk/src/rotation/high_water.rs`).
26	 * Atomicity is NOT this layer's job -- it is owned by the concrete
27	 * `HighWaterStore` adapter: the browser's `idbPutFloors`/`idbPersistWrappedKey`
28	 * (`apps/web/src/services/rotation-state.service.ts`) already read the
29	 * existing COMBINED record back INSIDE the same IndexedDB `readwrite`
30	 * transaction and write `Math.max(existing, value)` per numeric field, so a
31	 * concurrent tab's higher write can never be clobbered by a lower one --
32	 * matching the Rust store's `tokio::sync::Mutex`-guarded, max-preserving
33	 * `JsonSidecarFloorStore::put`.
34	 *
35	 * SC#4/D-06 (CLOSED, 70.1-02): `enforceResolved`'s cross-store sequencing --
36	 * formerly `bumpFloor(generationStore)` THEN `bumpFloor(seqStore)`, two
37	 * separate non-atomic writes to two separate IndexedDB object stores -- was
38	 * a DOC-ONLY residual flagged by Phase 70
39	 * (`.planning/todos/pending/2026-07-02-rotation-hardening-followups-from-pr-review.md`
40	 * item 1). This phase collapses BOTH floors into ONE combined per-nodeId
41	 * record (`CombinedFloorRecord`) written via a SINGLE `store.put` call --
42	 * the cross-store sequencing window no longer exists because there is only
43	 * one store. D-07 additionally folds the SC#3 wrapped-key checkpoint
44	 * ciphertext into this SAME combined record (see
45	 * `apps/web/src/services/rotation-state.service.ts`'s
46	 * `persistWrappedKey`/`getWrappedKey`/`deleteWrappedKey`).
47	 */
48	
49	/**
50	 * Persisted combined per-nodeId record (SC#4/D-06, SC#3/D-07): both
51	 * anti-rollback floors PLUS the optional ECIES wrapped-key checkpoint
52	 * ciphertext, all in ONE record so a single store write is atomic across
53	 * all three fields. `wrappedKeyCheckpoint` is a ciphertext blob -- it is
54	 * never numerically compared/maxed, only overwritten or cleared.
55	 */
56	export interface CombinedFloorRecord {
57	  generation?: number;
58	  seq?: number;
59	  wrappedKeyCheckpoint?: string;
60	}
61	
62	/**
63	 * A durable key-value seam for the COMBINED per-nodeId floor record. Replaces
64	 * the prior two-store (`generationStore`/`seqStore`) seam: one get/put pair
65	 * now carries generation, seq, AND the optional wrapped-key checkpoint in a
66	 * single record, so `enforceResolved` writes both floors atomically.
67	 */
68	export interface HighWaterStore {
69	  get(nodeId: string): Promise<CombinedFloorRecord | undefined>;
70	  /**
71	   * Writes the FULL combined record for `nodeId`. Concrete adapters (e.g.
72	   * the browser's IndexedDB-backed store) MUST max-preserve `generation`/
73	   * `seq` against any existing record inside the SAME write transaction --
74	   * this orchestration layer already computes the candidate max before
75	   * calling `put`, but a concurrent writer (another tab) may have raised the
76	   * floor since this layer's own read, so the concrete store's own
77	   * max-preserving write is the real safety net.
78	   */
79	  put(nodeId: string, record: CombinedFloorRecord): Promise<void>;
80	}
81	
82	/** Parameters supplied to enforceResolved for a freshly-resolved IPNS record. */
83	export interface EnforceResolvedParams {
84	  nodeId: string;
85	  seq: number;
86	  generation: number;
87	  /** Owner-vouched cold-device floor applied only on first contact (no local seq floor yet). */
88	  versionFloor: number;
89	}
90	
91	/** Thrown when a resolved generation regresses below the durable generation floor. */
92	export class GenerationRegressionError extends Error {
93	  constructor(nodeId: string, floor: number, attempted: number) {
94	    super(
95	      `Generation regression rejected for node ${nodeId}: floor=${floor}, attempted=${attempted}`
96	    );
97	    this.name = 'GenerationRegressionError';
98	  }
99	}
100	
101	/** Thrown when a resolved seq regresses below the durable seq floor (or cold-device versionFloor). */
102	export class SequenceRegressionError extends Error {
103	  constructor(nodeId: string, floor: number, attempted: number) {
104	    super(
105	      `Sequence regression rejected for node ${nodeId}: floor=${floor}, attempted=${attempted}`
106	    );
107	    this.name = 'SequenceRegressionError';
108	  }
109	}
110	
111	/**
112	 * Validates a value read back from a HighWaterStore. Fail-closed (V5):
113	 * anything that is not a non-negative safe integer is treated as absent
114	 * rather than coerced to a low floor.
115	 */
116	function isValidFloorValue(value: unknown): value is number {
117	  return (
118	    typeof value === 'number' &&
119	    Number.isInteger(value) &&
120	    Number.isSafeInteger(value) &&
121	    value >= 0
122	  );
123	}
124	
125	/**
126	 * Reads the combined record from the store, applying V5 fail-closed
127	 * validation independently to `generation` and `seq` -- a malformed value in
128	 * ONE field never poisons the other, and never poisons the ciphertext blob.
129	 */
130	async function readCombined(store: HighWaterStore, nodeId: string): Promise<CombinedFloorRecord> {
131	  const raw = await store.get(nodeId);
132	  return {
133	    generation: isValidFloorValue(raw?.generation) ? raw?.generation : undefined,
134	    seq: isValidFloorValue(raw?.seq) ? raw?.seq : undefined,
135	    wrappedKeyCheckpoint:
136	      typeof raw?.wrappedKeyCheckpoint === 'string' ? raw.wrappedKeyCheckpoint : undefined,
137	  };
138	}
139	
140	/**
141	 * Conditionally raises ONE field of the combined record to `candidate`, only
142	 * if it is higher than the current stored value (monotonic-max) -- writing
143	 * the FULL combined record back (preserving the other field and the
144	 * wrapped-key checkpoint untouched) via a single `store.put` call.
145	 */
146	async function bumpField(
147	  store: HighWaterStore,
148	  nodeId: string,
149	  field: 'generation' | 'seq',
150	  candidate: number
151	): Promise<void> {
152	  // V5 applies to writes too: never persist a malformed candidate (NaN,
153	  // negative, fractional) -- the floor stays where it is.
154	  if (!isValidFloorValue(candidate)) {
155	    return;
156	  }
157	  const current = await readCombined(store, nodeId);
158	  const currentValue = current[field];
159	  if (currentValue === undefined || candidate > currentValue) {
160	    await store.put(nodeId, { ...current, [field]: candidate });
161	  }
162	}
163	
164	/** The durable rotation high-water state machine returned by createRotationHighWater. */
165	export interface RotationHighWater {
166	  getGenerationFloor(nodeId: string): Promise<number | undefined>;
167	  bumpGeneration(nodeId: string, generation: number): Promise<void>;
168	  /** Owner-vouched first-contact seed -- raises the generation floor only if higher (never lowers it). */
169	  seedFromGrant(nodeId: string, rootGeneration: number): Promise<void>;
170	  getSeqFloor(nodeId: string): Promise<number | undefined>;
171	  bumpSeq(nodeId: string, seq: number): Promise<void>;
172	  /**
173	   * Fail-closed pre-unseal gate: compares a freshly-resolved seq/generation
174	   * against the stored floors. Throws a distinguishable regression error on
175	   * any regression; on first contact (no local seq floor) applies the
176	   * cold-device versionFloor gate; otherwise bumps both floors monotonic-max
177	   * in ONE combined-record write (SC#4/D-06 -- no cross-store sequencing
178	   * window).
179	   *
180	   * This is a pure pass/throw decision -- it never returns or computes any
181	   * AAD/unseal parameter.
182	   */
183	  enforceResolved(params: EnforceResolvedParams): Promise<void>;
184	}
185	
186	/**
187	 * Creates a durable rotation high-water state machine over a SINGLE injected
188	 * combined `HighWaterStore` seam (SC#4/D-06). Holds no in-instance cache:
189	 * every read/write goes through the injected store.
190	 */
