    crate::write_ops::rotation_deps::ApiClientTransport {
        api: fs.api.as_ref(),
        inodes: &fs.inodes,
    },
    fs.public_key.to_vec(),
    fs.private_key.to_vec(),
    fs.rotation_checkpoint_store.clone(),
);
