              // folderTree simply return undefined here (unchanged fallback
              // behavior for those nodes).
              nodeKeySource: (ipnsName) => {
                const folder = this.folderTree.get(ipnsName);
                if (!folder) return undefined;
                return {
                  publicKey: new Uint8Array(folder.ipnsKeypair.publicKey),
                  privateKey: new Uint8Array(folder.ipnsKeypair.privateKey),
                  writeKey: new Uint8Array(folder.writeKey),
                };
