1	//! Grant-root scope-computation building block, shared by BOTH platforms.
2	//!
3	//! This is the one piece of grant-root scope awareness with no TS analog: the
4	//! TS client never had a mounted filesystem tree to walk (design §3.9). It has
5	//! two halves:
6	//!
7	//! 1. **Ancestor walk (novel):** [`ancestor_ipns_chain`] computes a mutated
8	//!    inode's leaf-first ancestor IPNS-name chain by walking `parent_ino` up
9	//!    to `ROOT_INO` in the already-mounted [`crate::inode::InodeTable`] —
10	//!    O(depth), purely local, NO network call.
11	//! 2. **Grant-set source (Pitfall 2):** [`SentSharesCache`] is a local cache of
12	//!    the authenticated user's sent shares, refreshed out-of-band (mount init
13	//!    / periodic — see [`refresh_sent_shares`]) from
14	//!    `cipherbox_api_client::shares::collect_sent_shares` (69-03). It is never
15	//!    queried synchronously per-mutation (T-69-07-01).
16	//!
17	//! [`build_coverage_params`] and [`grant_root_for`] both WRAP
18	//! `cipherbox_sdk::rotation::scope::has_covering_grant` (69-05) — they do NOT
19	//! reimplement the coverage predicate (Pitfall 1).
20	//!
21	//! Hoisted here (rather than duplicated per platform) so BOTH the Unix write
22	//! handlers (69-11) and the Windows write handlers (69-14) consume the SAME
23	//! ancestor-walk + `has_covering_grant` call site (T-69-07-03).
24	
25	use std::collections::HashSet;
26	use std::future::Future;
27	
28	use cipherbox_api_client::shares::{collect_sent_shares, SentShareResponse};
29	use cipherbox_api_client::{ApiClient, ApiError};
30	use cipherbox_core::node::SealedChildRef;
31	use cipherbox_sdk::rotation::scope::{
32	    has_covering_grant, CoverageParams, LocalGrantRecord, ScopeExitResult,
33	};
34	use cipherbox_sdk::rotation::RotationError;
35	use cipherbox_sdk::RotateReadResult;
36	
37	use crate::inode::{InodeKind, InodeTable, ROOT_INO};
38	
39	// ---------------------------------------------------------------------------
40	// Ancestor walk — purely local, zero network calls
41	// ---------------------------------------------------------------------------
42	
43	/// Compute the mutated node's leaf-first ancestor IPNS-name chain by walking
44	/// `parent_ino` from `start_ino` up to `ROOT_INO` in the already-mounted
45	/// `InodeTable`.
46	///
47	/// Leaf-first: the node itself is first (its own IPNS name, if any — a
48	/// `Folder`/`Root`'s `ipns_name` or a resolved `File`'s
49	/// `file_meta_ipns_name`), the vault root is last. O(depth) — a single pass
50	/// up the tree already held in memory. NO IPNS resolve / api-client / network
51	/// call (design §3.9; the anti-pattern this guards against is resolving
52	/// ancestry over the network).
53	pub fn ancestor_ipns_chain(inodes: &InodeTable, start_ino: u64) -> AncestorChain {
54	    let mut names = Vec::new();
55	    let mut visited = HashSet::new();
56	    let mut current_ino = start_ino;
57	    let mut reached_root = false;
58	
59	    loop {
60	        // Cycle guard: a well-formed tree never revisits an inode, but this
61	        // keeps the walk O(depth)-bounded even over corrupt/synthetic state
62	        // rather than looping forever. A cycle means the walk did NOT reach
63	        // ROOT_INO cleanly (D-15b) — `reached_root` stays `false`.
64	        if !visited.insert(current_ino) {
65	            break;
66	        }
67	
68	        // A missing inode (dangling `parent_ino`, corrupt/synthetic state)
69	        // also means the walk did NOT reach ROOT_INO cleanly (D-15b).
70	        let Some(inode) = inodes.get(current_ino) else {
71	            break;
72	        };
73	
74	        match &inode.kind {
75	            // node/v3: Root/Folder/File all carry a plain `ipns_name: String`.
76	            // An empty string (Root pre-init, or a never-published File)
77	            // contributes nothing to the chain.
78	            InodeKind::Root { ipns_name, .. }
79	            | InodeKind::Folder { ipns_name, .. }
80	            | InodeKind::File { ipns_name, .. } => {
81	                if !ipns_name.is_empty() {
82	                    names.push(ipns_name.clone());
83	                }
84	            }
85	        }
86	
87	        if current_ino == ROOT_INO {
88	            reached_root = true;
89	            break;
90	        }
91	        current_ino = inode.parent_ino;
92	    }
93	
94	    AncestorChain {
95	        names,
96	        reached_root,
97	    }
98	}
99	
100	/// Result of walking a mutated node's ancestor chain up to `ROOT_INO`.
101	///
102	/// `reached_root` distinguishes a CLEAN walk (terminated at `ROOT_INO`) from
103	/// one that broke early on a missing inode or a cycle. [`gate_scope_exit`]
104	/// treats `reached_root == false` as fail-closed (D-15b MAJOR) — a partial
105	/// chain must NEVER be treated as a clean "no grant found" walk, since it may
106	/// have omitted the true grant-root ancestor.
107	#[derive(Debug, Clone, PartialEq, Eq)]
108	pub struct AncestorChain {
109	    /// Leaf-first IPNS-name chain: the mutated node itself first, the vault
110	    /// root last (when `reached_root` is `true`).
111	    pub names: Vec<String>,
112	    /// `true` only if the walk reached `ROOT_INO` cleanly — no missing
113	    /// inode, no cycle.
114	    pub reached_root: bool,
115	}
116	
